html:
{% set approved_by_user = doc.ts_approved_by or '' %}
{% set is_ceo = frappe.db.get_value('Has Role', {'parent': approved_by_user, 'role': 'CEO'}, 'name') if approved_by_user else '' %}
{% set is_md = frappe.db.get_value('Has Role', {'parent': approved_by_user, 'role': 'MD'}, 'name') if approved_by_user else '' %}
{% set is_approved = doc.ts_approval_status == 'Approved' and doc.docstatus == 1 %}
{% set is_draft = doc.docstatus == 0 %}

<style>
@page { size: A4; margin: 6mm 8mm 6mm 8mm; }
body { font-family: Arial, sans-serif; font-size: 10px; color: #000; }
.bbpl-wrap { position: relative; }
.bbpl-header-table { width: 100%; border-collapse: collapse; border: none; padding: 0 0 6px 0; }
.bbpl-header-table td { border: none !important; padding: 0; vertical-align: middle; }
.bbpl-logo-cell { width: 110px; padding-left: 6px !important; }
.bbpl-logo-cell img { max-width: 95px; max-height: 75px; }
.bbpl-header-text { text-align: center; padding-right: 110px !important; }
.bbpl-header-bottom-rule { border-bottom: 2px solid #000; margin: 0 0 6px 0; height: 0; line-height: 0; }
.bbpl-cname { font-size: 20px; font-weight: bold; color: #000; letter-spacing: 0.5px; line-height: 1.2; }
.bbpl-caddr { font-size: 12px; font-weight: bold; text-decoration: underline; margin-top: 2px; }
.bbpl-cinfo { font-size: 10px; margin-top: 3px; color: #111; }
.bbpl-cinfo span { margin: 0 6px; }
.bbpl-title-block { text-align: center; margin: 6px 0 4px 0; }
.bbpl-draft-stamp { font-size: 13px; font-weight: bold; letter-spacing: 2px; margin-bottom: 2px; }
.bbpl-title { font-size: 16px; font-weight: bold; text-decoration: underline; letter-spacing: 1px; }
.bbpl-info-table { width: 100%; border-collapse: collapse; margin: 0 0 4px 0; }
.bbpl-info-table td { padding: 3px 6px; font-size: 11px; vertical-align: middle; border: 1px solid #000; }
.bbpl-info-label { font-weight: bold; width: 22%; background: #eee; text-align: center; }
.bbpl-info-value { width: 28%; text-align: center; }
.bbpl-items { width: 100%; border-collapse: collapse; margin: 4px 0 0 0; }
.bbpl-items th { background: #e8e8e8; border: 1px solid #000; padding: 4px 6px; font-size: 10px; text-align: center; font-weight: bold; }
.bbpl-items td { border: 1px solid #000; padding: 3px 6px; font-size: 11px; vertical-align: top; }
.bbpl-items .num { text-align: right; white-space: nowrap; }
.bbpl-items .ctr { text-align: center; }
.bbpl-items .item-spec { font-size: 10px; color: #111; margin-top: 3px; line-height: 1.4; }
.bbpl-items tfoot td { padding: 4px 6px; font-size: 11px; font-weight: bold; }
.bbpl-items tfoot .total-lbl { text-align: right; background: #eee; }
.bbpl-items tfoot .total-val { text-align: right; white-space: nowrap; }
.bbpl-items tfoot .grand .total-lbl, .bbpl-items tfoot .grand .total-val { background: #cce6ff; font-size: 12px; }
.bbpl-section-heading { font-size: 12px; font-weight: bold; text-decoration: underline; margin: 8px 0 3px; }
.bbpl-payment-table { width: 100%; border-collapse: collapse; margin: 3px 0; }
.bbpl-payment-table th { background: #eee; border: 1px solid #000; padding: 4px 6px; font-size: 10px; text-align: center; font-weight: bold; }
.bbpl-payment-table td { border: 1px solid #000; padding: 3px 6px; font-size: 11px; }
.bbpl-payment-table .ctr { text-align: center; }
.bbpl-payment-table .num { text-align: right; }
.bbpl-terms-body { font-size: 11px; line-height: 1.5; padding: 0 4px; }
.bbpl-terms-body p { margin: 3px 0; }
.bbpl-terms-body b { font-weight: bold; }
.bbpl-stamp-area { text-align: right; margin: 16px 20px 0 0; }
.bbpl-stamp-img { width: 90px; height: auto; opacity: 0.9; }
.bbpl-sig-label { text-align: right; font-size: 12px; font-weight: bold; padding-right: 25px; margin-top: 4px; }
.bbpl-footer { margin-top: 10px; border-top: 1px solid #000; padding-top: 5px; text-align: center; font-size: 10px; color: #111; line-height: 1.4; }
.bbpl-footer .fname { font-weight: bold; font-size: 11px; color: #000; }
.bbpl-watermark { position: fixed; top: 35%; left: 8%; font-size: 110px; color: rgba(255,0,0,0.08); font-weight: bold; transform: rotate(-30deg); -webkit-transform: rotate(-30deg); z-index: 0; letter-spacing: 18px; pointer-events: none; }
</style>

<div class="bbpl-wrap">

{% if is_draft %}<div class="bbpl-watermark">DRAFT</div>{% endif %}

{% if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head | safe }}</div>{% endif %}

{% if not letter_head or no_letterhead %}
<table class="bbpl-header-table">
<tr>
  <td class="bbpl-logo-cell">
    <img src="/files/client_logo.png" alt="BBPL" onerror="this.style.display='none'">
  </td>
  <td class="bbpl-header-text">
    <div class="bbpl-cname">BETUL BIOFUEL PVT LTD</div>
    <div class="bbpl-caddr">Bodi Junawani, Betul (M.P.)</div>
    <div class="bbpl-cinfo">
      <span><b>GSTN:-</b> 23AAJCB8781D1ZM</span>
    </div>
    <div class="bbpl-cinfo">
      <span><b>Email:-</b> betulbiofuelpvtld@gmail.com | <b>Mobile no:-</b> 7880138508</span>
    </div>
  </td>
</tr>
</table>
<div class="bbpl-header-bottom-rule"></div>
{% endif %}

<div class="bbpl-title-block">
  {% if is_draft %}<div class="bbpl-draft-stamp" style="color:#cc0000;">DRAFT</div>{% endif %}
  <div class="bbpl-title">PURCHASE ORDER</div>
</div>

<table class="bbpl-info-table">
<tr>
  <td class="bbpl-info-label">Purchase Order</td>
  <td class="bbpl-info-value">{{ doc.name }}</td>
  <td class="bbpl-info-label">Date</td>
  <td class="bbpl-info-value">{{ frappe.format(doc.transaction_date, {'fieldtype': 'Date'}) }}</td>
</tr>
<tr>
  <td class="bbpl-info-label">Supplier</td>
  <td class="bbpl-info-value">{{ doc.supplier_name or doc.supplier or '' }}</td>
  <td class="bbpl-info-label">Required By</td>
  <td class="bbpl-info-value">{{ frappe.format(doc.schedule_date, {'fieldtype': 'Date'}) if doc.schedule_date else '' }}</td>
</tr>
<tr>
  <td class="bbpl-info-label">Address</td>
  <td colspan="3" class="bbpl-info-value">{% set addr = frappe.get_doc('Address', doc.supplier_address) if doc.supplier_address else none %}{% if addr %}{{ addr.address_line1 or '' }}{% if addr.address_line2 %}, {{ addr.address_line2 }}{% endif %}{% if addr.city %}, {{ addr.city }}{% endif %}{% if addr.state %}, {{ addr.state }}{% endif %} {{ addr.pincode or '' }}{% endif %}</td>
</tr>
<tr>
  <td class="bbpl-info-label">Contact</td>
  <td class="bbpl-info-value">{{ doc.contact_display or '' }}</td>
  <td class="bbpl-info-label">Cost Center</td>
  <td class="bbpl-info-value">{{ doc.cost_center or '' }}</td>
</tr>
<tr>
  <td class="bbpl-info-label">Project</td>
  <td class="bbpl-info-value">{{ doc.ts_project or doc.project or '' }}</td>
  <td class="bbpl-info-label">Material Request No</td>
  <td class="bbpl-info-value">{% set mr_ref = '' %}{% for item in doc.items %}{% if item.material_request and not mr_ref %}{% set mr_ref = item.material_request %}{% endif %}{% endfor %}{{ mr_ref or 'No' }}</td>
</tr>
<tr>
  <td class="bbpl-info-label">Shipping Address</td>
  <td colspan="3" class="bbpl-info-value">{% set saddr = frappe.get_doc('Address', doc.shipping_address) if doc.shipping_address else none %}{% if saddr %}{{ (saddr.address_line1 or '') | e }}{% if saddr.address_line2 %}, {{ saddr.address_line2 | e }}{% endif %}{% if saddr.city %}, {{ saddr.city | e }}{% endif %}{% if saddr.state %}, {{ saddr.state | e }}{% endif %} {{ (saddr.pincode or '') | e }}{% endif %}</td>
</tr>
</table>

<table class="bbpl-items">
<thead>
<tr>
  <th style="width:30px">S.No</th>
  <th>Item</th>
  <th style="width:85px">Item Remark</th>
  <th style="width:50px">Quantity</th>
  <th style="width:40px">Unit</th>
  <th style="width:70px">Rate</th>
  <th style="width:45px">GST %</th>
  <th style="width:110px">Amount</th>
</tr>
</thead>
<tbody>
{% for item in doc.items %}
<tr>
  <td class="ctr">{{ loop.index }}</td>
  <td><b>{{ item.item_name or item.item_code }}</b>{% if item.description %}<div class="item-spec">{{ item.description | safe }}</div>{% endif %}</td>
  <td>{{ item.ts_item_remark or '' }}</td>
  <td class="num">{{ frappe.format(item.qty, {'fieldtype': 'Float', 'precision': 0}) }}</td>
  <td class="ctr">{{ item.uom or item.stock_uom }}</td>
  <td class="num">{{ frappe.format(item.rate, {'fieldtype': 'Currency'}) }}</td>
  <td class="ctr">{% if item.item_tax_template %}{% set _tpl = item.item_tax_template %}{% set _parts = _tpl.split('%') %}{% if _parts | length > 1 %}{% set _nums = _parts[0].replace('GST','').replace('-','').strip() %}{% if _nums %}{{ _nums }}%{% else %}0%{% endif %}{% else %}0%{% endif %}{% elif doc.taxes %}{{ doc.taxes[0].rate }}%{% else %}0%{% endif %}</td>
  <td class="num">{{ frappe.format(item.amount, {'fieldtype': 'Currency'}) }}</td>
</tr>
{% endfor %}
</tbody>
<tfoot>
<tr>
  <td colspan="7" class="total-lbl">Net Total</td>
  <td class="total-val">{{ frappe.format(doc.net_total, {'fieldtype': 'Currency'}) }}</td>
</tr>
{% for tax in doc.taxes %}
<tr>
  <td colspan="7" class="total-lbl">{{ tax.description or 'Tax' }}</td>
  <td class="total-val">{{ frappe.format(tax.tax_amount, {'fieldtype': 'Currency'}) }}</td>
</tr>
{% endfor %}
<tr class="grand">
  <td colspan="7" class="total-lbl">Grand Total</td>
  <td class="total-val">{{ frappe.format(doc.grand_total, {'fieldtype': 'Currency'}) }}</td>
</tr>
</tfoot>
</table>

<div style="text-align:center; font-weight:bold; font-style:italic; background:#fff8e1; border:1px solid #f1c40f; padding:6px; font-size:11px; margin:6px 0 4px 0;">⚠ Note: All invoice entries must match the details in the purchase order.</div>

{% if doc.payment_schedule %}
{% set _includes_gst = doc.ts_payment_amount_includes_gst if doc.get('ts_payment_amount_includes_gst') is not none else 1 %}
{% set _has_tax = doc.grand_total and doc.net_total and doc.grand_total != doc.net_total %}
{% set _decompose = (not _includes_gst) and _has_tax %}
{% set _ns = namespace(has_gst=false) %}{% for _tx in (doc.taxes or []) %}{% if 'GST' in (_tx.description or '') or 'GST' in (_tx.account_head or '') %}{% set _ns.has_gst = true %}{% endif %}{% endfor %}
{% set _suffix = '+ GST' if _ns.has_gst else '+ Tax' %}
<div class="bbpl-section-heading">Payment Terms</div>
<table class="bbpl-payment-table">
<thead><tr><th>Due Date</th><th>Payment Term</th><th>Description</th><th>Invoice Portion</th><th>Payment Amount</th></tr></thead>
<tbody>
{% for ps in doc.payment_schedule %}
<tr>
  <td class="ctr">{{ frappe.format(ps.due_date, {'fieldtype': 'Date'}) }}</td>
  <td>{{ (ps.payment_term or '') | e }}</td>
  <td>{{ ps.description or (frappe.db.get_value('Payment Term', ps.payment_term, 'description') if ps.payment_term else '') or '' }}</td>
  <td class="ctr">{{ ps.invoice_portion }}%</td>
  <td class="num">{% if _decompose %}{{ frappe.format((ps.invoice_portion or 0) / 100.0 * doc.net_total, {'fieldtype': 'Currency'}) }}{% else %}{{ frappe.format(ps.payment_amount, {'fieldtype': 'Currency'}) }}{% endif %}</td>
</tr>
{% endfor %}
</tbody>
</table>
{% endif %}

{% if doc.taxes and (doc.grand_total or 0) > (doc.net_total or 0) and not doc.ts_payment_amount_includes_gst %}
{% set _g = namespace(cgst=0, sgst=0, igst=0) %}
{% for _t in doc.taxes %}{% set _hay = ((_t.account_head or '') ~ ' ' ~ (_t.description or '')) | upper %}{% if 'CGST' in _hay %}{% set _g.cgst = _g.cgst + (_t.tax_amount or 0) %}{% elif 'SGST' in _hay or 'UTGST' in _hay %}{% set _g.sgst = _g.sgst + (_t.tax_amount or 0) %}{% elif 'IGST' in _hay %}{% set _g.igst = _g.igst + (_t.tax_amount or 0) %}{% endif %}{% endfor %}
{% set _gst_class = _g.cgst + _g.sgst + _g.igst %}
{% set _gst_diff = (doc.grand_total or 0) - (doc.net_total or 0) %}
{% set _gst_total = _gst_class if _gst_class > 0 else _gst_diff %}
{% if _gst_total > 0 %}
<div class="bbpl-section-heading">GST Breakdown</div>
<table class="bbpl-payment-table" style="width:45%;">
<thead><tr><th>Tax Type</th><th class="num">Amount</th></tr></thead>
<tbody>
{% if doc.ts_gst_due_date %}<tr><td>GST Due Date</td><td class="num">{{ frappe.utils.formatdate(doc.ts_gst_due_date) }}</td></tr>{% endif %}
{% if _gst_class > 0 %}{% if _g.cgst > 0 %}<tr><td>CGST</td><td class="num">{{ frappe.format(_g.cgst, {'fieldtype': 'Currency'}) }}</td></tr>{% endif %}{% if _g.sgst > 0 %}<tr><td>SGST</td><td class="num">{{ frappe.format(_g.sgst, {'fieldtype': 'Currency'}) }}</td></tr>{% endif %}{% if _g.igst > 0 %}<tr><td>IGST</td><td class="num">{{ frappe.format(_g.igst, {'fieldtype': 'Currency'}) }}</td></tr>{% endif %}{% else %}<tr><td>GST</td><td class="num">{{ frappe.format(_gst_diff, {'fieldtype': 'Currency'}) }}</td></tr>{% endif %}
<tr><td><b>Total GST Amount</b></td><td class="num"><b>{{ frappe.format(_gst_total, {'fieldtype': 'Currency'}) }}</b></td></tr>
</tbody>
</table>
{% endif %}
{% endif %}

{% set has_overrides = doc.ts_deduction_overrides and doc.ts_deduction_overrides|length > 0 %}
{% if has_overrides or doc.tc_name or doc.terms %}
<div class="bbpl-section-heading">Terms and Conditions</div>
{% endif %}

{% if has_overrides %}
<div class="bbpl-terms-body">
  <p><b>Deduction Terms:</b></p>
  <table class="bbpl-payment-table" style="margin: 4px 0 8px 0;">
    <thead>
      <tr>
        <th>Deduction</th>
        <th>Rate</th>
        <th>Unit</th>
        <th>Reason / Note</th>
      </tr>
    </thead>
    <tbody>
    {% for od in doc.ts_deduction_overrides %}
      {% set effective_rate = od.override_rate if od.override_rate and od.override_rate > 0 else od.default_rate %}
      {% set effective_unit = od.override_rate_type if od.override_rate_type else od.default_rate_type %}
      <tr>
        <td>{{ od.deduction_label or od.deduction_code }}</td>
        <td class="num">{{ frappe.format(effective_rate, {'fieldtype': 'Float', 'precision': 2}) }}</td>
        <td class="ctr">{{ effective_unit or '' }}</td>
        <td>{{ od.override_reason or '' }}</td>
      </tr>
    {% endfor %}
    </tbody>
  </table>
</div>
{% endif %}

{% if doc.tc_name or doc.terms %}
<div class="bbpl-terms-body">
  {% if has_overrides %}<p><b>Other Terms:</b></p>{% endif %}
  {{ doc.terms or '' | safe }}
</div>
{% endif %}

<div class="bbpl-stamp-area">
{% if is_approved and is_ceo %}
  <img src="/files/CEO.jpeg" class="bbpl-stamp-img">
  <div class="bbpl-sig-label">Authorized Signatory<br><span style="font-weight:normal;font-size:10px;">CEO</span></div>
{% elif is_approved and is_md %}
  <img src="/files/MD.jpeg" class="bbpl-stamp-img">
  <div class="bbpl-sig-label">Authorized Signatory<br><span style="font-weight:normal;font-size:10px;">Managing Director</span></div>
{% else %}
  <div class="bbpl-sig-label">Authorized Signatory</div>
{% endif %}
</div>

<div class="bbpl-footer">
  <div class="fname">BETUL BIOFUEL PVT LTD</div>
  <div>Bodi Junawani, Betul (M.P.)</div>
  <div>GSTN:- 23AAJCB8781D1ZM</div>
  <div>Email:- betulbiofuelpvtld@gmail.com | Mobile no:- 7880138508</div>
</div>

</div>
